('g5_2_sci_u3_L01_basic#10','sci',5,2,'u3','L01','g5_2_sci_u3_L01_basic','lesson_basic','SC5-2-u3-C1',3,'error','auto','붙임딱지 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u3-X03','SC5-2-u3-X01','SC5-2-u3-X02']::text[],false,'{"seq":10,"concept":"SC5-2-u3-C1","difficulty":3,"kind":"error","stem":"붙임딱지 놀이를 하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"지안 — 「얼음물에 담갔다 꺼낸 손을 대야 더 빨리 변해.」","correct":true,"mis_target":"SC5-2-u3-X03"},{"t":"도현 — 「따뜻한 물이 든 컵에 대도 색이 바뀌어.」","mis":"SC5-2-u3-X01"},{"t":"수빈 — 「손을 떼면 천천히 원래 색으로 돌아와.」","mis":"SC5-2-u3-X02"}],"explanation":["붙임딱지는 따뜻함에 변해요.","차가운 손은 아니에요.","지안의 말이 잘못됐어요."]}'::jsonb),
('g5_2_sci_u3_L01_challenge#1','sci',5,2,'u3','L01','g5_2_sci_u3_L01_challenge','lesson_challenge','SC5-2-u3-C1',2,'match','auto','붙임딱지 놀이 장면과 알맞은 변화를 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SC5-2-u3-C1","difficulty":2,"kind":"match","stem":"붙임딱지 놀이 장면과 알맞은 변화를 이으세요.","pairs":[{"l":"색이 바뀌는 붙임딱지에 손 대기","r":"다른 색으로 바뀜"},{"l":"투명해지는 붙임딱지에 손 대기","r":"아래 글씨가 보임"},{"l":"손을 떼고 기다리기","r":"원래대로 돌아옴"}],"mis":"SC5-2-u3-X02","explanation":["손을 대면 변해요.","두 가지로 변해요.","떼면 돌아와요."]}'::jsonb),
