('g5_2_sci_u3_review_d#22','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C22',3,'match','auto','열의 이동 방식과 일어나는 곳, 막는 물건을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"SC5-2-u3-C22","difficulty":3,"kind":"match","stem":"열의 이동 방식과 일어나는 곳, 막는 물건을 알맞게 이으세요.","pairs":[{"l":"전도 — 고체","r":"주방 장갑"},{"l":"대류 — 액체와 기체","r":"닫은 창문"},{"l":"복사 — 빛","r":"양산"}],"mis":"SC5-2-u3-X31","explanation":["장갑은 닿는 열을 막아요.","창문은 공기 흐름을 막아요.","양산은 햇빛을 막아요."]}'::jsonb),
('g5_2_sci_u3_review_d#23','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C6',4,'mc','auto','뜨거운 코코아 컵을 두 손으로 감싸 쥐었어요. 일어나는 일을 가장 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u3-X12','SC5-2-u3-X11','SC5-2-u3-X09']::text[],false,'{"seq":23,"concept":"SC5-2-u3-C6","difficulty":4,"kind":"mc","stem":"뜨거운 코코아 컵을 두 손으로 감싸 쥐었어요. 일어나는 일을 가장 바르게 말한 것은 어느 것인가요?","options":[{"t":"컵의 열이 손으로 이동해 손은 따뜻해지고 코코아는 조금 식는다","correct":true},{"t":"손의 냉기가 컵으로 가서 코코아가 식는다","mis":"SC5-2-u3-X12"},{"t":"손의 열이 컵으로 가서 코코아가 더 뜨거워진다","mis":"SC5-2-u3-X11"},{"t":"손만 따뜻해지고 코코아의 온도는 그대로이다","mis":"SC5-2-u3-X09"}],"explanation":["컵이 더 뜨거워요.","열이 손으로 와요.","둘 다 변해요."]}'::jsonb),
('g5_2_sci_u3_review_d#24','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C16',4,'mc','auto','텐트 안 난로 옆에 쇠 국자를 두었어요. 일어나는 일을 열의 이동 방식과 가장 바르게 이은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X14','SC5-2-u3-X12','SC5-2-u3-X25']::text[],false,'{"seq":24,"concept":"SC5-2-u3-C16","difficulty":4,"kind":"mc","stem":"텐트 안 난로 옆에 쇠 국자를 두었어요. 일어나는 일을 열의 이동 방식과 가장 바르게 이은 것은 어느 것인가요?","options":[{"t":"난로 빛을 받은 국자가 데워지고(복사), 그 열이 국자 손잡이로 퍼진다(전도)","correct":true},{"t":"국자 손잡이가 먼저 뜨거워지고 그다음 국자 머리가 데워진다(대류)","mis":"SC5-2-u3-X14"},{"t":"국자의 냉기가 난로로 가서 국자가 데워진다(전도)","mis":"SC5-2-u3-X12"},{"t":"국자는 난로에 닿지 않아 데워지지 않는다","mis":"SC5-2-u3-X25"}],"explanation":["난로 빛을 받아요.","국자를 따라 퍼져요.","복사와 전도예요."]}'::jsonb),
('g5_2_sci_u3_review_d#25','sci',5,2,'u3','','g5_2_sci_u3_review_d','unit_review','SC5-2-u3-C20',4,'mc','auto','두 모둠의 장치를 공정하게 견주는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u3-X34','SC5-2-u3-X04']::text[],false,'{"seq":25,"concept":"SC5-2-u3-C20","difficulty":4,"kind":"mc","stem":"두 모둠의 장치를 공정하게 견주는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"같은 온도의 물을 같은 양만큼 넣고 같은 시간 뒤에 같은 온도계로 잰다","correct":true},{"t":"한 모둠은 따뜻한 물, 한 모둠은 차가운 물을 넣는다","mis":"SC5-2-u3-X34"},{"t":"장치의 색깔이 더 예쁜 쪽을 고른다","mis":"SC5-2-u3-X34"},{"t":"한 장치만 재고 다른 장치는 손으로 만져 본다","mis":"SC5-2-u3-X04"}],"explanation":["조건을 같게 해요.","같은 시간에 재요.","공정하게 견줘요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SC5-2-u4-C1','sci',5,2,'u4',1,'풍력 발전기와 풍력 발전 모형 — 풍력 발전기는 바람으로 회전 날개를 돌려 에너지를 만듦 · 산 위나 바닷가에서 볼 수 있고 길쭉한 날개가 세 개 · 모형도 회전 날개가 달려 있어 바람이 불면 돌아가고, 바람이 셀수록 빨리 돎',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],1),
('SC5-2-u4-C2','sci',5,2,'u4',1,'회전 날개를 돌려 전구에 불 켜기 — 입으로 가운데를 세게 불기·빨대로 비스듬히 불기·머리 말리개 바람으로 날개를 돌림 · 날개가 빠르게 돌 때만 전구에 불이 켜짐(날개가 돌아갈 때 불을 켤 에너지가 만들어짐) · 날개에 입술·손을 가까이 대지 않고 머리 말리개에 데지 않게 조심 · 페달 밟기처럼 내 몸으로 에너지를 만드는 방법도 떠올려 봄',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],2),
('SC5-2-u4-C3','sci',5,2,'u4',2,'자원의 뜻 — 우리가 생활하거나 물건을 생산할 때 이용하는 물·나무·철 같은 원료 · 목마를 때 마시는 물, 책을 만드는 나무, 자동차를 만드는 철',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],3),
('SC5-2-u4-C4','sci',5,2,'u4',2,'물·산림·광물 자원의 이용 — 물 자원(마시기·씻기·농사·물건 생산), 산림 자원(목재로 집·가구·종이, 버섯·잣, 생물의 보금자리), 광물 자원(석재·철근으로 건물, 철·구리로 스마트 기기, 석탄으로 에너지, 금·은 장신구) · 이용 카드를 같은 자원끼리 분류함',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],4),
('SC5-2-u4-C5','sci',5,2,'u4',2,'자원의 유한성 — 물: 지구의 물 총량은 줄지 않지만 오염된 물이 다시 쓸 수 있게 되기까지 오래 걸려 쓸 수 있는 깨끗한 물은 점점 부족해짐 · 산림: 마구 베거나 숲을 농경지로 바꾸면 다시 자라는 데 오래 걸려 줄어듦 · 광물: 묻혀 있는 양이 한정되고 다시 만들어지기 어려움 · 재활용으로 되쓰는 자원이 있어도 자원이 끝없이 있는 것은 아님',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],5),
('SC5-2-u4-C6','sci',5,2,'u4',2,'자원을 아껴 써야 하는 까닭 — 인구가 늘고 편리한 생활을 하려고 자원 사용량이 늘어남 · 한정된 자원을 무분별하게 쓰면 부족해지고, 지나친 사용은 환경오염·기후변화도 부름 · 자원을 조사할 때는 믿을 수 있는 출처인지 확인함',ARRAY['[6과08-01] 우리가 생활에서 이용하는 다양한 자원을 조사하고, 자원의 유한함을 설명할 수 있다.']::text[],6),
('SC5-2-u4-C7','sci',5,2,'u4',3,'에너지와 재생 에너지 — 에너지는 생물이 살아가거나 기계를 움직이는 데 필요하며 석탄·석유·태양 빛·바람·물 등 여러 자원에서 얻음 · 태양 빛·바람·물처럼 자연에서 얻고 계속 이용할 수 있는 에너지가 재생 에너지 · 석탄·석유는 쓸수록 줄어 재생 에너지가 아님',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],7),
('SC5-2-u4-C8','sci',5,2,'u4',3,'재생 에너지의 종류 — 태양 에너지(태양 빛을 많이 쓰고 태양열도 씀 — 태양 전지로 가로등·시계·인공위성), 풍력(바람으로 발전기), 수력(높은 곳에서 낮은 곳으로 떨어지는 물의 흐름), 해양 에너지(밀물과 썰물·파도·바닷물 흐름·온도 차이), 지열 에너지(땅속 깊은 곳의 열 — 사계절 온도가 거의 같아 냉난방에), 바이오 에너지(나무·풀·가축의 분뇨·음식물 쓰레기)',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],8),
('SC5-2-u4-C9','sci',5,2,'u4',3,'지역에 알맞은 재생 에너지 — 재생 에너지는 날씨와 지형의 영향을 많이 받음 · 바람이 센 섬·바닷가·산 위는 풍력, 햇빛이 강한 곳은 태양 에너지, 가축을 많이 기르는 곳은 바이오 에너지, 물이 세차게 흐르는 골짜기는 수력, 밀물과 썰물이 큰 바다는 해양 에너지 · 지역의 특징을 보고 고름',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],9),
('SC5-2-u4-C10','sci',5,2,'u4',3,'재생 에너지가 주목받는 까닭과 한계 — 석탄·석유는 양이 한정되고 대기오염·기후변화에 영향을 줌 → 재생 에너지는 자연에서 계속 얻고 환경오염에 영향을 적게 줘 주목받음 · 그러나 늘 일정한 양을 얻기 어렵고 설치 비용이 많이 들며 시설을 지을 때 생태계에 영향을 주기도 함 → 기술 발전이 필요함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],10),
('SC5-2-u4-C11','sci',5,2,'u4',4,'지속가능한 에너지 이용 — 지금 세대의 필요를 채우면서 미래 세대가 쓸 에너지도 지키는 것 · 재생 에너지는 계속 쓸 수 있지만 지금은 생산량이 충분하지 않음 · 미래 세대도 깨끗한 에너지를 쓰고 기후변화에 대응하려면 지속가능하게 써야 함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],11),
('SC5-2-u4-C12','sci',5,2,'u4',4,'지속가능한 예와 그렇지 않은 예 — 지속가능한 예: 냉난방 적정 온도 유지, 태양 에너지·수력·풍력 이용, 가까운 곳은 걷거나 자전거, 친환경 제품, 절약 캠페인, 여러 나라의 협력 · 그렇지 않은 예: 창문을 연 채 난방, 빈방 조명, 보지 않는 텔레비전, 가까운 거리도 늘 자동차, 석유로 얻어 이산화 탄소 발생, 에너지를 많이 쓰는 기계 · 놀이판의 사다리와 미끄럼틀로 분류함',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],12),
('SC5-2-u4-C13','sci',5,2,'u4',4,'에너지를 지속가능하게 이용하는 방법 — 세 갈래: 재생 가능한 자원에서 재생 에너지 얻기, 환경을 덜 오염시키고 사용량을 줄이는 친환경 기술(전기차·수소차) 개발, 일상에서 불필요한 에너지 사용 줄이기 · 학교 실천: 이동 수업 때 전등 끄기, 겨울에 교실 문 닫기, 쓰지 않는 전기 기구 플러그 뽑기',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],13),
('SC5-2-u4-C14','sci',5,2,'u4',5,'효율과 에너지 소비 효율 등급 — 효율이 좋다는 것은 같은 일을 하면서 에너지를 적게 쓰는 것(같은 밝기를 내며 전기를 적게 쓰는 전등) · 에너지 소비 효율 등급은 1~5등급이고 1등급에 가까울수록 효율이 높음 · 전원을 꺼도 플러그를 꽂아 두면 전기가 조금씩 쓰임(대기 전력) — 플러그 뽑기·절전 멀티탭',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],14),
('SC5-2-u4-C15','sci',5,2,'u4',5,'자원을 효율적으로 이용하는 방법 — 물: 물 받아 쓰기, 절수 장치, 움직임 센서 수도꼭지, 빗물 저금통 · 산림: 이면지, 손수건·다회용 컵, 전자 영수증, 나무 심고 가꾸기, 목재 제품 고쳐 쓰기 · 광물: 분리배출로 재활용(혼합물의 분리), 대체 자원 개발 · 과대 포장 물건 사지 않기 · 물·산림·광물을 함께 따짐',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],15),
('SC5-2-u4-C16','sci',5,2,'u4',5,'에너지를 효율적으로 이용하는 방법 — 1등급에 가까운 제품·LED 조명 쓰기, 절전 기능·플러그 뽑기·알맞은 냉난방 온도 같은 절약 습관, 태양 에너지·지열 에너지 같은 재생 에너지 쓰기, 외벽·지붕·창틀 단열로 열 손실 줄이기 · 효율적으로 쓰면 돈도 아끼고 환경도 지킴',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],16),
('SC5-2-u4-C17','sci',5,2,'u4',6,'집 모형 실험 설계 — 크기·모양이 같은 집 모형 두 개 · 둘 다 창문 안쪽에 뽁뽁이 한 장, 한 개에만 한 장 더 붙이고 우드록·색점토로 단열하고 틈을 막음 · 두 집 지붕에 탐침 온도계를 꽂고 미리 데운 같은 손난로를 넣어 5분 데운 뒤, 손난로를 빼고 1분 간격으로 5번 잼 · 탐침 끝은 바닥에 닿지 않게 공기 온도를 재고 뾰족한 끝은 사람을 향하지 않게 · 단열 말고 다른 조건은 같게',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],17),
('SC5-2-u4-C18','sci',5,2,'u4',6,'집 모형 결과 해석 — 온도 변화량은 처음 온도에서 5분 뒤 온도를 뺀 값 · 단열한 집이 온도 변화가 더 작음 → 집 안 온도를 잘 지켜 에너지 효율이 더 높음 · 처음 온도가 다르면 마지막 온도가 아니라 변화량으로 견줌',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],18),
('SC5-2-u4-C19','sci',5,2,'u4',6,'집에서 에너지를 효율적으로 이용하는 방법 — 열이 빠져나가지 않게 막기: 단열재, 이중창·삼중창, 햇빛 방향에 따라 움직이는 차양, 실내 온도를 지키는 열 교환기, 옥상 정원 · 에너지를 직접 만들기: 태양 빛으로 전기, 땅속 열로 냉난방 · 불 끄는 날(어스아워)처럼 절약을 함께 실천함',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],19),
('SC5-2-u4-C20','sci',5,2,'u4',7,'실천 영상 만들고 나누기 — 생활에서 실제로 할 수 있는 방법(양치 컵, 음식 남기지 않기, 분리배출, 쓰지 않는 전원 끄기, 대중교통·자전거)을 주제로 정함 · 감독·대본·촬영·소품 역할을 나누고 장면을 스토리 보드에 글과 그림으로 · 남을 비하하거나 불쾌한 내용·개인 정보는 넣지 않고 안전한 곳에서 찍으며 소품은 재활용품으로 · 공유하고 바르고 고운 말로 댓글, 나부터 꾸준히 실천',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],20),
('SC5-2-u4-C21','sci',5,2,'u4',8,'미래 에너지 전문가 — 재생 에너지 전문가: 재생 에너지원을 연구해 더 좋은 태양 전지·풍력 발전기를 만들고, 알맞은 설치 장소를 찾고, 중요성을 알림 · 에너지 하베스팅(수확) 전문가: 새어 나오는 조명 빛, 자동차의 떨림, 뜨거운 물의 열, 걸을 때 누르는 힘, 체온처럼 버려지는 에너지를 모아 쓰는 방법을 연구 · 놀이터 바닥·그네 같은 아이디어',ARRAY['[6과08-02] 재생 에너지의 종류를 조사하고, 에너지를 지속가능하게 이용하는 방법에 관심을 갖는다.']::text[],21),
('SC5-2-u4-C22','sci',5,2,'u4',8,'자원과 에너지 정리 — 물·산림·광물 자원은 한정되어 아껴 써야 함 · 재생 에너지·친환경 기술·절약으로 에너지를 지속가능하게 씀 · 1등급 제품·단열·재활용·빗물 재사용으로 자원과 에너지를 효율적으로 쓰고 생활에서 실천함',ARRAY['[6과08-03] 자원과 에너지의 효율적인 이용 방법에 대해 탐색하고, 생활 속에서 실천할 수 있는 다양한 사례를 공유할 수 있다.']::text[],22)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SC5-2-u4-X01','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'회전 날개가 천천히 돌거나 멈춰 있어도 전구에 불이 켜진다고 여긴다','빠르게 돌 때만'),
('SC5-2-u4-X02','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'바람을 약하게, 날개 끝에 불수록 날개가 잘 돌아 불이 잘 켜진다고 여긴다','가운데를 세게'),
('SC5-2-u4-X03','sci',5,'u4',ARRAY['SC5-2-u4-C1']::text[],'풍력 발전기가 바람 없이도 돈다고 여기거나 모형과의 공통점을 겉모습에서만 찾는다','바람으로 날개가 돌아요'),
('SC5-2-u4-X04','sci',5,'u4',ARRAY['SC5-2-u4-C2']::text[],'날개에 입술·손을 바짝 대거나 머리 말리개를 몸 가까이 대는 등 안전을 놓친다','입술·손은 멀리'),
('SC5-2-u4-X05','sci',5,'u4',ARRAY['SC5-2-u4-C3']::text[],'자원을 물건을 만드는 원료가 아닌 엉뚱한 것(쓰레기·날씨·기계)으로 여긴다','생활과 생산에 쓰는 원료'),
('SC5-2-u4-X06','sci',5,'u4',ARRAY['SC5-2-u4-C4']::text[],'자원을 이용하는 모습과 자원의 종류를 바꾸어 분류한다(종이컵을 광물, 석탄을 산림으로)','물 · 나무 · 땅속 광물'),
('SC5-2-u4-X07','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'물을 쓰면 지구의 물 총량이 줄어든다고 여긴다','총량은 그대로'),
('SC5-2-u4-X08','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'물은 돌고 도니 사람이 쓸 수 있는 깨끗한 물도 줄지 않는다고 여긴다','깨끗해지기까지 오래 걸려요'),
('SC5-2-u4-X09','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'나무는 다시 자라니 마구 베어도 산림 자원이 줄지 않는다고 여긴다','다시 자라는 데 오래'),
('SC5-2-u4-X10','sci',5,'u4',ARRAY['SC5-2-u4-C5']::text[],'광물 자원은 캐내어 써도 곧 다시 만들어진다고 여긴다','묻힌 양이 한정'),
('SC5-2-u4-X11','sci',5,'u4',ARRAY['SC5-2-u4-C5','SC5-2-u4-C6']::text[],'재활용·순환되는 사례를 보고 자원이 끝없이 있다고 여긴다','재활용해도 한정'),
('SC5-2-u4-X12','sci',5,'u4',ARRAY['SC5-2-u4-C6']::text[],'찾은 자료를 출처를 확인하지 않고 그대로 믿고 쓴다','믿을 수 있는 출처'),
('SC5-2-u4-X13','sci',5,'u4',ARRAY['SC5-2-u4-C7']::text[],'석탄·석유를 재생 에너지로 여기거나 태양 빛·바람도 쓰면 줄어든다고 여긴다','자연에서 계속'),
('SC5-2-u4-X14','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'재생 에너지 이름과 얻는 방법을 바꾸어 짝짓는다(수력을 밀물과 썰물로, 해양 에너지를 계곡 물로)','떨어지는 물 수력 · 바다 해양'),
('SC5-2-u4-X15','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'태양 에너지는 태양의 뜨거운 열만 이용한다고 여긴다','빛을 많이 써요'),
('SC5-2-u4-X16','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'지열 에너지를 땅 위 햇볕의 열로 여기거나 땅속 온도가 계절마다 크게 변한다고 여긴다','땅속 깊은 곳 · 사계절 비슷'),
('SC5-2-u4-X17','sci',5,'u4',ARRAY['SC5-2-u4-C8']::text[],'바이오 에너지의 재료를 놓친다(석탄·쇠붙이라고 여긴다)','식물 · 가축 분뇨 · 음식물 쓰레기'),
('SC5-2-u4-X18','sci',5,'u4',ARRAY['SC5-2-u4-C9']::text[],'지역의 특징과 맞지 않는 재생 에너지를 고른다','그 지역에 많은 것'),
('SC5-2-u4-X19','sci',5,'u4',ARRAY['SC5-2-u4-C10']::text[],'재생 에너지는 날씨와 상관없이 늘 같은 양을 얻고 비용·문제가 전혀 없다고 여긴다','날씨 · 비용 · 기술'),
('SC5-2-u4-X20','sci',5,'u4',ARRAY['SC5-2-u4-C10']::text[],'재생 에너지가 주목받는 까닭을 고갈·오염이 아닌 엉뚱한 것(모양·크기)에서 찾거나 오히려 오염을 많이 낸다고 여긴다','계속 · 깨끗하게'),
('SC5-2-u4-X21','sci',5,'u4',ARRAY['SC5-2-u4-C7','SC5-2-u4-C10']::text[],'석탄·석유를 자연에서 끝없이 얻을 수 있고 환경에도 문제가 없다고 여긴다','쓸수록 줄어요'),
('SC5-2-u4-X22','sci',5,'u4',ARRAY['SC5-2-u4-C11']::text[],'지속가능을 지금 세대가 마음껏 쓰는 것으로 여기고 미래 세대를 놓친다','미래 세대도'),
('SC5-2-u4-X23','sci',5,'u4',ARRAY['SC5-2-u4-C12']::text[],'에너지를 낭비하는 예를 지속가능하게 이용하는 예로 분류한다','불필요하게 쓰나'),
('SC5-2-u4-X24','sci',5,'u4',ARRAY['SC5-2-u4-C13']::text[],'지속가능하게 이용하는 방법을 한 가지로만 좁힌다(절약만, 또는 재생 에너지만)','재생 · 기술 · 절약 함께'),
('SC5-2-u4-X25','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'전원을 끄면 플러그를 꽂아 두어도 전기가 전혀 쓰이지 않는다고 여긴다','꽂혀 있으면 조금씩'),
('SC5-2-u4-X26','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'효율이 높다는 것을 에너지를 많이 쓰거나 세게 작동하는 것으로 여긴다','같은 일에 적게'),
('SC5-2-u4-X27','sci',5,'u4',ARRAY['SC5-2-u4-C14']::text[],'에너지 소비 효율 등급 숫자가 클수록 효율이 높다고 여긴다','1등급에 가까울수록'),
('SC5-2-u4-X28','sci',5,'u4',ARRAY['SC5-2-u4-C15']::text[],'자원을 낭비하는 행동(과대 포장 구입·일회용품·짧은 거리 자동차·물 틀어 놓기)을 효율적인 방법으로 고른다','덜 쓰고 다시 쓰기'),
('SC5-2-u4-X29','sci',5,'u4',ARRAY['SC5-2-u4-C16']::text[],'에너지 생산을 줄이고 사용을 늘리면 효율적이라고 여긴다','같은 일에 덜 쓰기'),
('SC5-2-u4-X30','sci',5,'u4',ARRAY['SC5-2-u4-C15']::text[],'물·산림·광물 자원을 아끼는 방법을 서로 바꾸어 짝짓는다(빗물 저금통을 광물, 분리배출을 물)','어떤 자원을 아끼나'),
('SC5-2-u4-X31','sci',5,'u4',ARRAY['SC5-2-u4-C17']::text[],'집 모형 실험에서 같게 할 조건(크기·손난로·재는 시간)을 다르게 한다','단열만 다르게'),
('SC5-2-u4-X32','sci',5,'u4',ARRAY['SC5-2-u4-C17']::text[],'탐침 끝을 바닥에 닿게 하거나 손난로를 뺄 때 문을 활짝 여는 등 측정을 흐트러뜨린다','공기 온도 · 살짝 열기'),
('SC5-2-u4-X33','sci',5,'u4',ARRAY['SC5-2-u4-C18']::text[],'온도 변화가 더 큰 집이 에너지 효율이 더 높다고 여긴다','덜 변한 집'),
('SC5-2-u4-X34','sci',5,'u4',ARRAY['SC5-2-u4-C18']::text[],'처음 온도가 다른데 마지막 온도만 견주거나 온도 변화량을 잘못 구한다','처음 − 나중'),
('SC5-2-u4-X35','sci',5,'u4',ARRAY['SC5-2-u4-C19']::text[],'열을 막는 방법과 에너지를 만드는 방법을 바꾸어 분류한다(이중창이 전기를 만든다고)','막기 · 만들기'),
('SC5-2-u4-X36','sci',5,'u4',ARRAY['SC5-2-u4-C19']::text[],'단열재가 스스로 열을 내 집을 데운다고 여긴다','막아서 지킬 뿐'),
('SC5-2-u4-X37','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'생활에서 실천할 수 없거나 자원·에너지와 상관없는 내용을 실천 영상 주제로 고른다','내가 할 수 있는 것'),
('SC5-2-u4-X38','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'영상에 개인 정보·남을 비하하는 내용을 넣거나 위험한 곳에서 찍고 댓글을 함부로 쓴다','지키고 존중하기'),
('SC5-2-u4-X39','sci',5,'u4',ARRAY['SC5-2-u4-C20']::text[],'영상을 한 번 만들어 올리면 실천은 끝났다고 여긴다','꾸준히'),
('SC5-2-u4-X40','sci',5,'u4',ARRAY['SC5-2-u4-C21']::text[],'에너지 하베스팅을 버려지는 에너지 모으기가 아닌 새 발전소 짓기·석탄 더 캐기로 여긴다','버려지는 에너지 모으기'),
('SC5-2-u4-X41','sci',5,'u4',ARRAY['SC5-2-u4-C21']::text[],'재생 에너지 전문가가 하는 일을 엉뚱하게(석유를 더 쓰게 하는 일로) 여긴다','재생 에너지를 더 잘'),
('SC5-2-u4-X42','sci',5,'u4',ARRAY['SC5-2-u4-C22']::text[],'재생 에너지가 있으니 자원과 에너지를 아낄 필요가 없다고 여긴다','아끼기도 함께')
