('g5_2_sci_u4_L04_basic#3','sci',5,2,'u4','L04','g5_2_sci_u4_L04_basic','lesson_basic','SC5-2-u4-C12',1,'mc','auto','에너지 이용 놀이판의 ⑤ 칸에 도착하면 말을 어떻게 옮기나요?',ARRAY['SC5-2-u4-X23']::text[],false,'{"seq":3,"concept":"SC5-2-u4-C12","difficulty":1,"kind":"mc","stem":"에너지 이용 놀이판의 ⑤ 칸에 도착하면 말을 어떻게 옮기나요?","options":[{"t":"사다리를 타고 위로 올라간다","correct":true},{"t":"미끄럼틀을 타고 아래로 내려간다","mis":"SC5-2-u4-X23"},{"t":"출발점으로 돌아간다","mis":"SC5-2-u4-X23"},{"t":"그 자리에서 놀이가 끝난다","mis":"SC5-2-u4-X23"}],"explanation":["⑤는 태양 전지판이에요.","지속가능한 예예요.","사다리로 올라가요."],"asset":{"type":"passage","lines":["① 냉난방할 때 알맞은 온도 지키기","② 창문을 연 채 난방 켜기","③ 가까운 곳은 걷거나 자전거 타기","④ 빈방에 조명 켜 두기","⑤ 지붕에 태양 전지판 달기","⑥ 보지 않는 텔레비전 켜 두기","⑦ 여러 나라가 함께 에너지 문제 풀기","⑧ 가까운 거리도 늘 자동차 타기"],"title":"에너지 이용 놀이판의 칸"}}'::jsonb),
