('g5_2_sci_u4_review_d#15','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C15',2,'mc','auto','산림 자원을 지키려고 섬 사람들이 할 수 있는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X09','SC5-2-u4-X28']::text[],false,'{"seq":15,"concept":"SC5-2-u4-C15","difficulty":2,"kind":"mc","stem":"산림 자원을 지키려고 섬 사람들이 할 수 있는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"나무를 벤 자리에 다시 나무를 심고 가꾼다","correct":true},{"t":"뒷산 나무를 한꺼번에 모두 벤다","mis":"SC5-2-u4-X09"},{"t":"숲을 모두 밭으로 바꾼다","mis":"SC5-2-u4-X09"},{"t":"나무 의자를 고치지 않고 바로 버린다","mis":"SC5-2-u4-X28"}],"explanation":["나무를 심어요.","가꿔요.","숲을 지켜요."]}'::jsonb),
('g5_2_sci_u4_review_d#16','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C18',2,'error','auto','누리반 탐방 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC5-2-u4-X33','SC5-2-u4-X34','SC5-2-u4-X31']::text[],false,'{"seq":16,"concept":"SC5-2-u4-C18","difficulty":2,"kind":"error","stem":"누리반 탐방 일지 ⑥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하겸 — 「단열 안 한 집이 더 많이 변했으니 효율이 더 높아.」","correct":true,"mis_target":"SC5-2-u4-X33"},{"t":"보은 — 「단열한 집은 1.8 °C만 낮아졌어.」","mis":"SC5-2-u4-X34"},{"t":"지후 — 「두 집 크기는 같았어.」","mis":"SC5-2-u4-X31"}],"explanation":["많이 변하면 열이 샜어요.","덜 변해야 좋아요.","하겸의 말이 잘못됐어요."],"asset":{"type":"passage","lines":["단열 안 한 집 — 처음 28.0 °C → 5분 뒤 23.6 °C","단열한 집(뽁뽁이 두 겹·우드록·색점토) — 처음 27.0 °C → 5분 뒤 25.2 °C","두 집은 크기가 같고, 같은 손난로로 데운 뒤 1분마다 쟀다."],"title":"⑥ 셋째 날 오후 — 집 모형 실험"}}'::jsonb),
('g5_2_sci_u4_review_d#17','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C18',3,'ox','auto','집 모형 실험에서 온도 변화량이 큰 집일수록 에너지 효율이 높아요.',ARRAY['SC5-2-u4-X33']::text[],false,'{"seq":17,"concept":"SC5-2-u4-C18","difficulty":3,"kind":"ox","stem":"집 모형 실험에서 온도 변화량이 큰 집일수록 에너지 효율이 높아요.","answer":"X","reason_options":[{"t":"온도 변화가 작아야 열이 덜 빠져나간 것이기 때문에","correct":true},{"t":"온도가 많이 변해야 열을 잘 지킨 것이기 때문에","mis":"SC5-2-u4-X33"}],"mis":"SC5-2-u4-X33","explanation":["변화량을 봐요.","작아야 좋아요.","큰 집은 열이 샜어요."]}'::jsonb),
('g5_2_sci_u4_review_d#18','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C19',3,'mc','auto','창이 한 겹이고 창틀 틈으로 바람이 새어 드는 섬 학교를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X35','SC5-2-u4-X33','SC5-2-u4-X23']::text[],false,'{"seq":18,"concept":"SC5-2-u4-C19","difficulty":3,"kind":"mc","stem":"창이 한 겹이고 창틀 틈으로 바람이 새어 드는 섬 학교를 고치는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"창을 이중창으로 바꾸고 창틀 틈을 막는다","correct":true},{"t":"창을 더 얇은 유리로 바꾼다","mis":"SC5-2-u4-X35"},{"t":"틈을 더 넓혀 바람을 잘 통하게 한다","mis":"SC5-2-u4-X33"},{"t":"난방기를 세게 켜고 창을 연다","mis":"SC5-2-u4-X23"}],"explanation":["창을 두 겹으로요.","틈을 막아요.","열을 지켜요."]}'::jsonb),
('g5_2_sci_u4_review_d#19','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C20',3,'mc','auto','누리반 탐방 일지 ⑦의 영상에 더 넣기 알맞은 장면은 어느 것인가요?',ARRAY['SC5-2-u4-X28','SC5-2-u4-X38','SC5-2-u4-X37']::text[],false,'{"seq":19,"concept":"SC5-2-u4-C20","difficulty":3,"kind":"mc","stem":"누리반 탐방 일지 ⑦의 영상에 더 넣기 알맞은 장면은 어느 것인가요?","options":[{"t":"설거지할 때 물을 받아 쓰는 모습","correct":true},{"t":"수도꼭지를 틀어 둔 채 자리를 비우는 모습","mis":"SC5-2-u4-X28"},{"t":"주민의 집 주소를 보여 주는 모습","mis":"SC5-2-u4-X38"},{"t":"물과 상관없는 놀이 장면","mis":"SC5-2-u4-X37"}],"explanation":["물 아끼기가 주제예요.","받아 써요.","알맞은 장면이에요."],"asset":{"type":"passage","lines":["주제 — 바람솔섬의 물 아끼기","장면 — 비누칠할 때 물 잠그기, 모은 빗물로 화분에 물 주기","지킬 점 — 주민의 얼굴과 이름은 허락 없이 넣지 않는다.","다 만든 영상은 학급 누리집에 올렸다."],"title":"⑦ 넷째 날 — 실천 영상 만들기"}}'::jsonb),
('g5_2_sci_u4_review_d#20','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C9',3,'ox','auto','햇빛이 거의 들지 않는 깊은 골짜기에는 태양 에너지보다 물의 흐름을 쓰는 수력이 더 알맞아요.',ARRAY['SC5-2-u4-X18']::text[],false,'{"seq":20,"concept":"SC5-2-u4-C9","difficulty":3,"kind":"ox","stem":"햇빛이 거의 들지 않는 깊은 골짜기에는 태양 에너지보다 물의 흐름을 쓰는 수력이 더 알맞아요.","answer":"O","reason_options":[{"t":"지역에 많은 자연을 이용하는 재생 에너지를 골라야 하기 때문에","correct":true},{"t":"어느 지역이든 태양 에너지만 알맞기 때문에","mis":"SC5-2-u4-X18"}],"mis":"SC5-2-u4-X18","explanation":["햇빛이 적어요.","물이 흘러요.","수력이 알맞아요."]}'::jsonb),
('g5_2_sci_u4_review_d#21','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C21',3,'mc','auto','재생 에너지 전문가가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X40','SC5-2-u4-X41']::text[],false,'{"seq":21,"concept":"SC5-2-u4-C21","difficulty":3,"kind":"mc","stem":"재생 에너지 전문가가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"더 좋은 태양 전지와 풍력 발전기를 연구하고 알맞은 설치 장소를 찾는다","correct":true},{"t":"버려지는 체온만 모은다","mis":"SC5-2-u4-X40"},{"t":"석탄을 더 많이 캔다","mis":"SC5-2-u4-X41"},{"t":"영상만 만든다","mis":"SC5-2-u4-X41"}],"explanation":["재생 에너지를 연구해요.","장소를 찾아요.","알려요."]}'::jsonb),
('g5_2_sci_u4_review_d#22','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C22',3,'match','auto','탐방에서 본 모습과 배운 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":22,"concept":"SC5-2-u4-C22","difficulty":3,"kind":"match","stem":"탐방에서 본 모습과 배운 내용을 알맞게 이으세요.","pairs":[{"l":"바닥난 돌 광산","r":"자원은 한정되어 있다"},{"l":"바닷가 둑의 발전 시설","r":"재생 에너지를 쓴다"},{"l":"1등급 냉장고","r":"에너지를 효율적으로 쓴다"}],"mis":"SC5-2-u4-X42","explanation":["광산은 바닥났어요.","둑은 바다를 써요.","냉장고는 효율적이에요."]}'::jsonb),
('g5_2_sci_u4_review_d#23','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C17',4,'mc','auto','집 모형 실험의 결과가 모둠마다 조금씩 달랐어요. 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SC5-2-u4-X34','SC5-2-u4-X31','SC5-2-u4-X32']::text[],false,'{"seq":23,"concept":"SC5-2-u4-C17","difficulty":4,"kind":"mc","stem":"집 모형 실험의 결과가 모둠마다 조금씩 달랐어요. 결과를 더 믿을 수 있게 하는 방법으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조건을 같게 하여 여러 번 되풀이하고 모둠 결과를 함께 견준다","correct":true},{"t":"가장 마음에 드는 결과 하나만 고른다","mis":"SC5-2-u4-X34"},{"t":"모둠마다 집 크기를 다르게 한다","mis":"SC5-2-u4-X31"},{"t":"탐침 끝을 바닥에 닿게 해 다시 잰다","mis":"SC5-2-u4-X32"}],"explanation":["되풀이해요.","조건을 같게 해요.","함께 견줘요."]}'::jsonb),
('g5_2_sci_u4_review_d#24','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C10',4,'mc','auto','재생 에너지의 좋은 점과 한계를 모두 바르게 말한 것은 어느 것인가요?',ARRAY['SC5-2-u4-X19','SC5-2-u4-X20','SC5-2-u4-X21']::text[],false,'{"seq":24,"concept":"SC5-2-u4-C10","difficulty":4,"kind":"mc","stem":"재생 에너지의 좋은 점과 한계를 모두 바르게 말한 것은 어느 것인가요?","options":[{"t":"계속 얻고 오염이 적지만, 날씨에 따라 양이 달라지고 비용이 많이 들어 기술 발전이 필요하다","correct":true},{"t":"한계는 하나도 없고 좋은 점만 있다","mis":"SC5-2-u4-X19"},{"t":"쓸수록 줄어들고 오염도 많이 낸다","mis":"SC5-2-u4-X20"},{"t":"석유처럼 묻힌 양이 정해져 있다","mis":"SC5-2-u4-X21"}],"explanation":["좋은 점이 있어요.","한계도 있어요.","기술이 필요해요."]}'::jsonb),
('g5_2_sci_u4_review_d#25','sci',5,2,'u4','','g5_2_sci_u4_review_d','unit_review','SC5-2-u4-C20',4,'mc','auto','누리반의 실천 영상을 본 섬 주민이 함께 실천하게 하려면 어떻게 하는 것이 가장 알맞은가요?',ARRAY['SC5-2-u4-X38','SC5-2-u4-X39','SC5-2-u4-X37']::text[],false,'{"seq":25,"concept":"SC5-2-u4-C20","difficulty":4,"kind":"mc","stem":"누리반의 실천 영상을 본 섬 주민이 함께 실천하게 하려면 어떻게 하는 것이 가장 알맞은가요?","options":[{"t":"주민들이 쉽게 따라 할 수 있는 실천을 보여 주고, 함께해 보자고 권하는 말을 넣는다","correct":true},{"t":"주민의 이름과 집을 영상에 크게 보여 준다","mis":"SC5-2-u4-X38"},{"t":"한 번 올리고 다시는 실천하지 않는다","mis":"SC5-2-u4-X39"},{"t":"섬 생활과 상관없는 장면을 넣는다","mis":"SC5-2-u4-X37"}],"explanation":["따라 하기 쉬워요.","함께하자고 해요.","실천이 퍼져요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO5-2-u3-C1','soc',5,2,'u3',1,'식민 통치·저항·광복 — 다른 나라가 힘으로 빼앗아 다스리는 것이 식민 통치, 그에 맞서 싸우는 것이 저항, 빼앗긴 나라를 되찾은 것이 광복 · 이 단원은 ① 식민 통치와 저항으로 달라진 사회와 생활 모습 → ② 8·15 광복과 6·25 전쟁으로 달라진 사회와 생활 모습 · 우리 민족은 감시 속에서도 나라를 되찾을 때까지 여러 방법으로 맞섬(사건을 외우기보다 생활이 어떻게 달라졌는지 따라감)',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],1),
('SO5-2-u3-C2','soc',5,2,'u3',1,'을사늑약과 외교권 — 조선의 왕이 황제가 되어 세운 나라가 대한 제국 · 한반도를 둘러싼 여러 나라의 다툼 속에 러시아와 싸워 이긴 일제가 본격적으로 침략 · 황제가 반대했는데도 군대를 앞세워 억지로 맺은 조약(늑약)으로 대한 제국은 일본을 거치지 않고는 다른 나라와 조약을 맺을 수 없게 되어 외교권을 빼앗김 · 소식을 들은 상인은 가게 문을 닫고 학생은 등교를 거부함',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],2),
('SO5-2-u3-C3','soc',5,2,'u3',1,'헤이그 특사 — 황제는 네덜란드 헤이그에서 열린 평화 회의에 특사를 보내 을사늑약이 무효임을 알리려 함 · 일제의 방해로 회의장에는 들어가지 못했지만 여러 나라 기자들 앞에서 대한 제국의 처지와 늑약의 부당함을 알림',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],3),
