('SO5-2-u3-C17','soc',5,2,'u3',5,'민족정신을 없애려는 정책과 강제 동원 — 아시아·태평양 곳곳에서 침략 전쟁을 일으킨 일제는 우리 민족이 일본 왕에게 충성하고 전쟁에 협조하게 하려고 신사에 강제로 절하게 하고, 성과 이름을 일본식으로 바꾸게 하고, 일본어를 강요하며 학교에서 우리말과 역사를 배우지 못하게 함 · 학생들은 몸뻬 교복을 입고 전쟁을 미화하는 수업과 군사 훈련을 받음 · 전쟁에 필요한 사람(전쟁터·공장 등)과 물자(놋그릇·숟가락까지)를 강제로 동원, 일부 여성은 일본군 ‘위안부’로 강제로 끌려가 큰 고통을 겪음',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],17),
('SO5-2-u3-C18','soc',5,2,'u3',5,'민족 문화를 지킨 노력과 한국광복군 — 탄압 속에서도 우리 역사를 연구해 일제의 역사 왜곡에 맞서고, 일제에 저항하는 글을 써 민족의식을 일깨움 · 대한민국 임시 정부는 한국광복군을 만들어 일본과의 전쟁에 나섬 · 미군과 협력해 국내로 들어갈 작전을 세웠지만 일제가 항복해 실행하지 못함',ARRAY['[6사06-01] 일제의 식민 통치와 이에 대한 저항이 사회와 생활에 미친 영향을 이해한다.']::text[],18),
('SO5-2-u3-C19','soc',5,2,'u3',6,'8·15 광복과 달라진 생활 — 임시 정부와 나라 안팎 독립운동가들의 끊임없는 노력 속에 연합국이 승리하며 우리 민족은 8월 15일 광복을 맞음 · 사람들은 태극기를 들고 만세를 부름, 감옥의 독립운동가가 풀려나고 나라 밖 동포와 임시 정부 지도자들이 돌아옴 · 학교에서 우리말로 수업하고 우리글·우리 역사를 배움, 일제가 강제로 없앤 한글 신문·잡지가 다시 나옴, 일본식 성과 이름 대신 원래 성과 이름을 씀',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],19),
('SO5-2-u3-C20','soc',5,2,'u3',6,'대한민국 정부 수립 — 일본군의 무장 해제를 이유로 38도선 남쪽에 미군, 북쪽에 소련군이 들어옴 · 우리 민족은 통일 정부를 세우려 했지만 남과 북, 미국과 소련의 의견이 달라 어려워짐 · 국제 연합(UN)의 결정으로 선거가 가능한 남한에서만 5·10 총선거를 치러 국회의원을 뽑음(우리 역사의 첫 민주 선거, 일정한 나이가 된 모든 국민이 남녀 구분 없이 참여) · 제헌 국회가 헌법을 만들어 공포(7월 17일, 제헌절) → 헌법에 따라 첫 대통령 선출 → 8월 15일 대한민국 정부 수립',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],20),
('SO5-2-u3-C21','soc',5,2,'u3',7,'6·25 전쟁의 전개 — 남과 북에 서로 다른 정부가 선 뒤 북한이 소련의 지원으로 군사력을 키워 무력으로 통일하려고 기습적으로 38도선을 넘어 쳐들어옴(남침) → 사흘 만에 서울을 빼앗기고 낙동강 남쪽까지 밀림 → 국제 연합이 여러 나라가 참여한 국제 연합군과 물자를 보냄 → 인천 상륙 작전으로 서울을 되찾고 압록강 부근까지 나아감 → 중국군 참전으로 다시 서울을 빼앗기고 물러남 → 서울을 되찾은 뒤 38도선 부근에서 치열한 전투와 회담이 이어짐 → 정전 협정(전투를 잠시 멈추기로 함)으로 휴전선이 정해짐(전쟁이 끝난 것이 아니라 멈춘 것)',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],21),
('SO5-2-u3-C22','soc',5,2,'u3',7,'전쟁 중 사람들의 생활 — 많은 사람이 고향을 떠나 피란함, 피란민이 낙동강 남쪽과 임시 수도 부산으로 모여 산등성이에 움막이나 판잣집을 짓고 삶 · 마실 물과 먹을 것이 부족해 줄을 서서 물을 받음 · 학생들은 임시로 만든 천막 학교에서 배움을 이어 감 · 흥남 철수: 중국군 참전으로 물러날 때 흥남 부두에서 군인과 피란민이 배로 빠져나옴(짐을 버리고 정원보다 훨씬 많은 피란민을 태운 배) · 밀면: 북쪽에서 내려온 피란민이 고향의 냉면을 부산에서 구할 수 있는 밀가루 등으로 만든 음식',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],22),
('SO5-2-u3-C23','soc',5,2,'u3',8,'6·25 전쟁의 피해와 오늘날까지 이어진 영향 — 군인뿐 아니라 많은 민간인이 목숨을 잃거나 다침 · 국토가 황폐해지고 집·산업 시설·도로·철도·다리가 파괴되고 수원 화성 같은 국가유산이 훼손됨 · 가족과 헤어진 이산가족과 부모를 잃은 전쟁고아가 많이 생기고 생활필수품과 먹을 것이 오래 부족함 · 남북이 서로를 적으로 여기는 감정이 깊어지고 분단이 오늘날까지 이어져 헤어진 가족을 끝내 만나지 못한 사람도 많음(방송국의 이산가족 찾기 생방송으로 다시 만난 가족도 있음)',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],23),
('SO5-2-u3-C24','soc',5,2,'u3',9,'기념일을 알리는 옷 만들기 — 단원에서 공부한 일과 관련된 기념일(삼일절·대한민국 임시 정부 수립 기념일·6·10 만세 운동 기념일·제헌절·광복절·학생 독립운동 기념일·유엔군 참전의 날 등)을 조사 → 기념하는 것·기념일이 된 까닭·그날 하는 일을 정리 → 핵심어를 뽑아 그림과 문구를 구상 → 옷을 완성해 소개 · 그림과 문구는 자유롭게 꾸며도 기념일의 뜻과 역사적 사실에 맞아야 함',ARRAY['[6사06-02] 8·15 광복과 6·25 전쟁이 사회와 생활에 미친 영향을 파악한다.']::text[],24)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO5-2-u3-X01','soc',5,'u3',ARRAY['SO5-2-u3-C1']::text[],'일제가 다스리던 시기에 우리 민족은 아무것도 못 하고 당하기만 했다고 여긴다','감시 속에서도 여러 방법으로 맞섬'),
('SO5-2-u3-X02','soc',5,'u3',ARRAY['SO5-2-u3-C1']::text[],'식민 통치·저항·광복의 뜻을 바꾸어 안다(광복을 나라를 빼앗긴 일로, 저항을 따르는 일로)','빼앗아 다스림 · 맞섬 · 되찾음'),
('SO5-2-u3-X03','soc',5,'u3',ARRAY['SO5-2-u3-C2']::text[],'을사늑약으로 대한 제국이 빼앗긴 권리를 잘못 안다(화폐·농사·학교를 세우는 권리라고)','다른 나라와 조약을 맺는 외교권'),
('SO5-2-u3-X04','soc',5,'u3',ARRAY['SO5-2-u3-C2']::text[],'을사늑약을 두 나라가 뜻을 모아 맺은 조약으로 여겨 「억지로 맺은 조약」이라는 뜻을 놓친다','황제 반대 · 군대를 앞세움'),
('SO5-2-u3-X05','soc',5,'u3',ARRAY['SO5-2-u3-C3']::text[],'헤이그 특사가 회의에서 늑약을 바로 없앴다고 여기거나, 아무 뜻 없는 실패였다고만 여긴다','회의장엔 못 들어감 · 기자들에게 알림'),
('SO5-2-u3-X06','soc',5,'u3',ARRAY['SO5-2-u3-C4']::text[],'의병에는 훈련받은 군인만 참여했다고 여긴다','나이·신분 다양 · 농민·여성도'),
('SO5-2-u3-X07','soc',5,'u3',ARRAY['SO5-2-u3-C4']::text[],'의병 운동이 더 활발해진 까닭이나 만주·연해주로 건너간 까닭을 놓친다','해산 군인 합류 · 큰 부대 탄압 → 나라 밖'),
('SO5-2-u3-X08','soc',5,'u3',ARRAY['SO5-2-u3-C5']::text[],'조선 총독부를 우리가 세운 정부(대한 제국·임시 정부)로 안다','일제가 다스리려고 세운 기관'),
('SO5-2-u3-X09','soc',5,'u3',ARRAY['SO5-2-u3-C5']::text[],'헌병 경찰과 칼을 찬 교사를 질서를 지키려는 일로만 보아 감시·탄압·공포의 뜻을 놓친다','감시해서 독립운동을 막음'),
('SO5-2-u3-X10','soc',5,'u3',ARRAY['SO5-2-u3-C6']::text[],'토지 조사 사업이 농민의 땅을 지켜 주려는 일이었다고 여긴다','내세운 까닭과 실제로 벌어진 일'),
('SO5-2-u3-X11','soc',5,'u3',ARRAY['SO5-2-u3-C6']::text[],'토지 조사 사업 뒤 자기 땅에서 농사짓는 농민이 늘었다고 거꾸로 안다','남의 땅을 빌려 짓는 농민이 늘어남'),
('SO5-2-u3-X12','soc',5,'u3',ARRAY['SO5-2-u3-C7']::text[],'나라 밖으로 간 독립운동가를 도망간 사람으로만 여긴다','나라 밖에서 힘을 길러 이어 간 저항'),
('SO5-2-u3-X13','soc',5,'u3',ARRAY['SO5-2-u3-C7']::text[],'신흥 무관 학교와 흥사단의 자리와 하는 일을 바꾸어 안다','만주 독립군 · 미국 실력'),
('SO5-2-u3-X14','soc',5,'u3',ARRAY['SO5-2-u3-C8']::text[],'3·1 운동이 서울에서 하루 만에 끝났거나 어른 한 무리만 참여했다고 여긴다','전국 · 석 달 넘게 · 여러 사람'),
('SO5-2-u3-X15','soc',5,'u3',ARRAY['SO5-2-u3-C8']::text[],'3·1 운동을 무기를 든 의병 싸움이나 다른 운동과 헷갈린다','독립 선언서 · 만세 시위'),
('SO5-2-u3-X16','soc',5,'u3',ARRAY['SO5-2-u3-C9']::text[],'임시 정부를 세운 곳과 까닭을 잘못 안다(서울에, 도망가려고)','상하이 · 탄압을 피함 · 외교'),
('SO5-2-u3-X17','soc',5,'u3',ARRAY['SO5-2-u3-C9']::text[],'임시 정부가 한 일과 일제가 한 일을 섞는다(토지 조사 사업을 임시 정부가 했다고)','비밀 연락망 · 신문 · 외교 활동'),
('SO5-2-u3-X18','soc',5,'u3',ARRAY['SO5-2-u3-C10']::text[],'한인 애국단을 흥사단·신흥 무관 학교와 헷갈린다','활동이 힘들 때 · 일제 주요 인물 처단'),
('SO5-2-u3-X19','soc',5,'u3',ARRAY['SO5-2-u3-C11']::text[],'3·1 운동 뒤 일제가 부드럽게 다스려 우리 민족의 생활이 나아졌다고 여긴다','방법만 바꿈 · 분열 · 쌀을 더 가져감'),
('SO5-2-u3-X20','soc',5,'u3',ARRAY['SO5-2-u3-C11']::text[],'쌀을 더 많이 생산했는데 농민이 더 배고팠던 까닭을 놓친다','쌀이 일본으로 실려 감'),
('SO5-2-u3-X21','soc',5,'u3',ARRAY['SO5-2-u3-C12']::text[],'물산 장려 운동·농촌 계몽 운동·조선어 학회가 한 일을 바꾸어 짝짓는다','토산품 · 한글 가르치기 · 우리말 사전'),
('SO5-2-u3-X22','soc',5,'u3',ARRAY['SO5-2-u3-C12']::text[],'물건·글·말로 힘을 기른 운동은 독립과 관계없다고 여기거나 무기를 든 싸움으로 안다','경제·글·말로 민족의 힘을 기름'),
('SO5-2-u3-X23','soc',5,'u3',ARRAY['SO5-2-u3-C13']::text[],'6·10 만세 운동과 광주 학생 항일 운동을 바꾸어 안다','장례식 날 서울 · 광주에서 차별에 맞서 전국으로'),
('SO5-2-u3-X24','soc',5,'u3',ARRAY['SO5-2-u3-C13']::text[],'광주 학생 항일 운동을 학생끼리의 단순한 다툼으로만 보아 쌓여 있던 차별을 놓친다','한국 학생만 붙잡음 · 학교 속 차별'),
('SO5-2-u3-X25','soc',5,'u3',ARRAY['SO5-2-u3-C14']::text[],'봉오동·청산리 전투를 나라 안에서 일어난 일이나 실력 기르기 운동으로 안다','만주 · 독립군 · 무장 투쟁'),
('SO5-2-u3-X26','soc',5,'u3',ARRAY['SO5-2-u3-C12','SO5-2-u3-C14']::text[],'나라 안 실력 기르기와 나라 밖 무장 투쟁 가운데 하나만 독립에 필요했다고 여긴다','둘이 함께 독립을 향함'),
('SO5-2-u3-X27','soc',5,'u3',ARRAY['SO5-2-u3-C15']::text[],'일제가 철도와 항구를 우리 민족을 위해 놓았다고 여긴다','군대 이동 · 자원을 일본으로'),
('SO5-2-u3-X28','soc',5,'u3',ARRAY['SO5-2-u3-C15']::text[],'도시가 커지면서 모든 사람이 근대 문물을 똑같이 누렸다고 여긴다','일본인이 산 곳 · 한국인이 산 곳 · 토막집'),
('SO5-2-u3-X29','soc',5,'u3',ARRAY['SO5-2-u3-C16']::text[],'인공 조미료와 배달 문화를 모든 한국인이 누린 좋은 변화로만 본다','편리함과 그늘이 함께'),
('SO5-2-u3-X30','soc',5,'u3',ARRAY['SO5-2-u3-C17']::text[],'민족정신을 없애려는 정책의 까닭을 잘못 안다(우리 문화를 아껴서, 공부를 잘하라고)','일본 왕에 충성 · 침략 전쟁에 협조'),
('SO5-2-u3-X31','soc',5,'u3',ARRAY['SO5-2-u3-C17']::text[],'강제 동원을 사람들이 원해서 간 일이나 물건만 가져간 일로 여긴다','사람과 물자를 모두 강제로'),
('SO5-2-u3-X32','soc',5,'u3',ARRAY['SO5-2-u3-C18']::text[],'한국광복군이 나라 안으로 들어와 일본군을 몰아냈다고 여기거나 의병과 헷갈린다','임시 정부가 만듦 · 작전 준비 중 일제 항복'),
('SO5-2-u3-X33','soc',5,'u3',ARRAY['SO5-2-u3-C18']::text[],'역사 연구와 글쓰기는 저항이 아니라고 여긴다','역사 왜곡에 맞섬 · 민족의식을 일깨움'),
('SO5-2-u3-X34','soc',5,'u3',ARRAY['SO5-2-u3-C19']::text[],'광복이 연합국의 승리만으로 저절로 왔다고 여겨 우리 민족의 끊임없는 노력을 놓친다','독립운동 + 연합국 승리'),
('SO5-2-u3-X35','soc',5,'u3',ARRAY['SO5-2-u3-C19']::text[],'광복 뒤 달라진 생활을 거꾸로 안다(일본어 수업이 늘었다고, 일본식 이름을 계속 썼다고)','우리말 수업 · 원래 이름 · 한글 신문'),
('SO5-2-u3-X36','soc',5,'u3',ARRAY['SO5-2-u3-C20']::text[],'대한민국 정부가 세워지는 차례를 바꾼다(정부 수립 뒤 총선거, 대통령 뒤 헌법)','총선거 → 헌법 → 대통령 → 정부 수립'),
('SO5-2-u3-X37','soc',5,'u3',ARRAY['SO5-2-u3-C20']::text[],'38도선 남북에 들어온 군대를 바꾸거나 처음부터 남북이 따로 나라를 세우려 했다고 여긴다','남쪽 미군 · 북쪽 소련군 · 통일 정부 노력'),
('SO5-2-u3-X38','soc',5,'u3',ARRAY['SO5-2-u3-C20']::text[],'5·10 총선거를 일부 사람만 뽑은 선거나 남북 모두에서 치른 선거로 안다','남한에서만 · 첫 민주 선거 · 남녀 모두'),
('SO5-2-u3-X39','soc',5,'u3',ARRAY['SO5-2-u3-C21']::text[],'6·25 전쟁을 남한이 먼저 일으켰다고 하거나 전쟁이 펼쳐진 차례를 바꾼다','남침 → 낙동강 → 인천 상륙 → 압록강 → 중국군 → 정전'),
('SO5-2-u3-X40','soc',5,'u3',ARRAY['SO5-2-u3-C21']::text[],'정전 협정으로 전쟁이 완전히 끝났다고 여긴다','전투를 잠시 멈춤 · 휴전선 · 분단'),
('SO5-2-u3-X41','soc',5,'u3',ARRAY['SO5-2-u3-C22']::text[],'전쟁 중에는 배움이 완전히 멈췄다고 여기거나 피란민의 생활을 편했다고 여긴다','천막 학교 · 움막·판잣집 · 물 부족'),
('SO5-2-u3-X42','soc',5,'u3',ARRAY['SO5-2-u3-C21','SO5-2-u3-C22']::text[],'인천 상륙 작전과 흥남 철수를 바꾸어 안다','인천 = 서울 되찾음 · 흥남 = 피란민을 태운 배'),
